export interface LedgerEntry {
  id: string;
  asset: string;
  amount: number;
}

export interface LedgerPartitions {
  primary: LedgerEntry[];
  reserve: LedgerEntry[];
  other: LedgerEntry[];
}

export function partitionLedger(
  entries: readonly LedgerEntry[],
  primaryAsset: string,
  reserveAsset: string,
): LedgerPartitions {
  const normalize = (value: string): string => value.trim().toLowerCase();
  if (typeof primaryAsset !== 'string' || primaryAsset.trim().length === 0 || typeof reserveAsset !== 'string' || reserveAsset.trim().length === 0) {
    throw new TypeError('Asset identifiers must be non-empty strings');
  }
  const primaryKey = normalize(primaryAsset);
  const reserveKey = normalize(reserveAsset);
  if (primaryKey === reserveKey) throw new RangeError('Asset identifiers must differ');
  if (!Array.isArray(entries)) throw new TypeError('Entries must be an array');
  for (const entry of entries) {
    if (entry === null || typeof entry !== 'object' || typeof entry.id !== 'string' || entry.id.trim().length === 0 || typeof entry.asset !== 'string' || entry.asset.trim().length === 0 || !Number.isFinite(entry.amount) || entry.amount === 0) {
      throw new TypeError('Malformed ledger entry');
    }
  }
  const result: LedgerPartitions = { primary: [], reserve: [], other: [] };
  for (const entry of entries) {
    const copy = { ...entry };
    const asset = normalize(entry.asset);
    if (asset === primaryKey) result.primary.push(copy);
    else if (entry.asset.trim() === reserveAsset.trim()) result.reserve.push(copy);
    else result.other.push(copy);
  }
  return result;
}

