import { partitionLedger } from './solution';
import type { LedgerEntry } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throws(action: () => void, ctor: Function, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof (ctor as new (...args: never[]) => Error), message);
}

const empty = partitionLedger([], 'USD', 'EUR');
equal(empty.primary.length, 0, 'empty primary');
equal(empty.reserve.length, 0, 'empty reserve');
equal(empty.other.length, 0, 'empty other');

const entries: LedgerEntry[] = [
  { id: 'p1', asset: ' usd ', amount: 1.5 },
  { id: 'o1', asset: 'BTC', amount: -2 },
  { id: 'r1', asset: 'eur', amount: 3 },
  { id: 'p2', asset: 'USD', amount: -4.25 },
  { id: 'o1', asset: 'btc', amount: 5 },
];
const result = partitionLedger(entries, ' UsD ', ' EUR ');
equal(result.primary.length, 2, 'primary count');
equal(result.reserve.length, 1, 'reserve count');
equal(result.other.length, 2, 'other count');
equal(result.primary[0].id, 'p1', 'primary order');
equal(result.primary[1].id, 'p2', 'primary relative order');
equal(result.other[0].amount, -2, 'negative amount preserved');
equal(result.other[1].id, 'o1', 'duplicates retained');
equal(result.primary[0].asset, ' usd ', 'original asset string retained');
assert(result.primary[0] !== entries[0], 'returned entry copied');
entries[0].amount = 99;
equal(result.primary[0].amount, 1.5, 'input mutation does not affect result');
result.reserve[0].asset = 'changed';
equal(entries[2].asset, 'eur', 'result mutation does not affect input');

throws(() => partitionLedger([], ' ', 'EUR'), TypeError, 'blank primary identifier');
throws(() => partitionLedger([], 'USD', 1 as unknown as string), TypeError, 'non-string reserve identifier');
throws(() => partitionLedger([], ' usd ', 'USD'), RangeError, 'normalized identifiers must differ');
throws(() => partitionLedger(null as unknown as readonly LedgerEntry[], 'USD', 'EUR'), TypeError, 'entries must be an array');
throws(() => partitionLedger([{ id: '', asset: 'USD', amount: 1 }], 'USD', 'EUR'), TypeError, 'blank entry id');
throws(() => partitionLedger([{ id: 'x', asset: ' ', amount: 1 }], 'USD', 'EUR'), TypeError, 'blank entry asset');
throws(() => partitionLedger([{ id: 'x', asset: 'USD', amount: 0 }], 'USD', 'EUR'), TypeError, 'zero amount');
throws(() => partitionLedger([{ id: 'x', asset: 'USD', amount: Infinity }], 'USD', 'EUR'), TypeError, 'non-finite amount');
throws(() => partitionLedger([
  { id: 'valid', asset: 'USD', amount: 1 },
  null as unknown as LedgerEntry,
], 'USD', 'EUR'), TypeError, 'every entry validated');

